3	use tiny_skia as sk;
4	use typst_library::layout::{Abs, Axes, Point, Ratio, Size};
5	use typst_library::visualize::{
6	    Geometry, Gradient, Paint, ProcessColor, RelativeTo, Shape, Tiling,
7	};
8	
9	use crate::{AbsExt, State, to_sk_transform};
10	
11	/// Trait for sampling of a paint, used as a generic
12	/// abstraction over solid colors and gradients.
13	pub trait PaintSampler: Copy {
14	    /// Sample the color at the `pos` in the pixmap.
15	    fn sample(self, pos: (u32, u32)) -> sk::PremultipliedColorU8;
16	}
17	
18	impl PaintSampler for sk::PremultipliedColorU8 {
19	    fn sample(self, _: (u32, u32)) -> sk::PremultipliedColorU8 {
20	        self
21	    }
22	}
23	
24	/// State used when sampling colors for text.
25	///
26	/// It caches the inverse transform to the parent, so that we can
27	/// reuse it instead of recomputing it for each pixel.
28	#[derive(Copy, Clone)]
29	pub struct GradientSampler<'a> {
30	    gradient: &'a Gradient,
31	    container_size: Size,
32	    transform_to_parent: sk::Transform,
33	}
34	
35	impl<'a> GradientSampler<'a> {
36	    pub fn new(
37	        gradient: &'a Gradient,
38	        state: &State,
39	        item_size: Size,
40	        on_text: bool,
41	    ) -> Self {
42	        let relative = gradient.unwrap_relative(on_text);
43	        let container_size = match relative {
44	            RelativeTo::Self_ => item_size,
45	            RelativeTo::Parent => state.size,
46	        };
47	
48	        let fill_transform = match relative {
49	            RelativeTo::Self_ => sk::Transform::identity(),
50	            RelativeTo::Parent => state.container_transform.invert().unwrap(),
51	        };
52	
53	        Self {
54	            gradient,
55	            container_size,
56	            transform_to_parent: fill_transform,
57	        }
58	    }
59	}
60	
61	impl PaintSampler for GradientSampler<'_> {
62	    /// Samples a single point in a glyph.
63	    fn sample(self, (x, y): (u32, u32)) -> sk::PremultipliedColorU8 {
64	        // Compute the point in the gradient's coordinate space.
65	        let mut point = sk::Point { x: x as f32, y: y as f32 };
66	        self.transform_to_parent.map_point(&mut point);
67	
68	        // Sample the gradient
69	        to_sk_color_u8(
70	            self.gradient
71	                .sample_at(
72	                    (point.x, point.y),
