14	/// Render a text run into the canvas.
15	pub fn render_text(canvas: &mut sk::Pixmap, state: State, text: &TextItem) {
16	    let mut x = Abs::zero();
17	    let mut y = Abs::zero();
18	    for glyph in &text.glyphs {
19	        let id = GlyphId(glyph.id);
20	        let x_offset = x + glyph.x_offset.at(text.size);
21	        let y_offset = y + glyph.y_offset.at(text.size);
22	
23	        if should_outline(&text.font, id) {
24	            let state = state.pre_translate(Point::new(x_offset, -y_offset));
25	            render_outline_glyph(canvas, state, text, id);
26	        } else {
27	            let upem = text.font.units_per_em();
28	            let text_scale = text.size / upem;
29	            let state = state
30	                .pre_translate(Point::new(x_offset, -y_offset))
31	                .pre_scale(Axes::new(text_scale, text_scale));
32	
33	            if let Some(frame) = glyph_frame(&text.font, glyph.id) {
34	                crate::render_frame(canvas, state, &frame.into());
35	            }
36	        }
37	
38	        x += glyph.x_advance.at(text.size);
39	        y += glyph.y_advance.at(text.size);
40	    }
41	}
42	
43	/// Render an outline glyph into the canvas. This is the "normal" case.
44	fn render_outline_glyph(
45	    canvas: &mut sk::Pixmap,
46	    state: State,
47	    text: &TextItem,
48	    id: GlyphId,
49	) -> Option<()> {
50	    let ts = &state.transform;
51	    let ppem = text.size.to_f32() * ts.sy;
52	
53	    // Render a glyph directly as a path. This only happens when the fast glyph
54	    // rasterization can't be used due to very large text size or weird
55	    // scale/skewing transforms.
56	    if ppem > 100.0
57	        || ppem < 0.0
58	        || ts.kx != 0.0
59	        || ts.ky != 0.0
60	        || ts.sx != ts.sy
61	        || text.stroke.is_some()
62	    {
63	        let path = {
64	            let mut builder = WrappedPathBuilder(sk::PathBuilder::new());
65	            text.font.ttf().outline_glyph(id, &mut builder)?;
66	            builder.0.finish()?
67	        };
68	
69	        let scale = text.size.to_f32() / text.font.units_per_em() as f32;
70	
71	        let mut pixmap = None;
72	
73	        let rule = sk::FillRule::default();
74	
